#!/bin/sh
# usage: frag2_chain.sh <gpu> <AB|A|B> : wait for the running fold trainings, then train on frag2 targets and decode
G=$2
until grep -q FOLD_A_DONE /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/train_fold_A.log 2>/dev/null && grep -q FOLD_B_DONE /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/train_fold_B.log 2>/dev/null; do sleep 60; done
export CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=$1 HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 TOKENIZERS_PARALLELISM=false KF_VAL=miami_Tsel600 KF_TAG=_frag2 KF_MANIFEST=manifest_frag2.jsonl KF_REFS=refs_frag2.csv KF_EXTRA_FRAC=0 KF_AUG=0
cd /kaggle/working/omni_rt/work
/kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_train.py /home/jovyan/work/Enes/lost_in_transcription/cache/huggingface/hub/models--CohereLabs--cohere-transcribe-03-2026/snapshots/b1eacc2686a3d08ceaae5f24a88b1d519620bc09 /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/${G}_frag2 --group $G --lr 1e-5 --seed 1 --patience 4 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/train_${G}_frag2.log 2>&1
if [ $G = AB ]; then
  /kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_decode.py /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/AB_frag2/best /kaggle/working/omni_rt/dev /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/kfold/hyps/cohere_frag2_ondev.csv es 16 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/dec_AB_frag2_dev.log 2>&1
  /kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_decode.py /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/AB_frag2/best /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/input_enspa/miami_kfold/miami_T /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/kfold/hyps/cohere_frag2_onT.csv es 32 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/dec_AB_frag2_T.log 2>&1
else
  if [ $G = A ]; then OTHER=B; else OTHER=A; fi
  for tgt in $OTHER T; do /kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_decode.py /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/${G}_frag2/best /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/input_enspa/miami_kfold/miami_$tgt /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/kfold/hyps/cohere_train${G}_frag2_on$tgt.csv es 32 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/dec_${G}_frag2_$tgt.log 2>&1; done
  /kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_decode.py /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/${G}_frag2/best /kaggle/working/omni_rt/dev /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/kfold/hyps/cohere_train${G}_frag2_ondev.csv es 16 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/dec_${G}_frag2_dev.log 2>&1
fi
echo FRAG2_${G}_DONE >> /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/train_${G}_frag2.log
